INSERT INTO lr_questions (section_id, qid, preptest, section, question_number, question_type, stimulus, prompt, correct_choice, is_explained, source_note) SELECT s.id, $batch07$PT128-S3-Q4$batch07$, 128, 3, 4, $batch07$Agree/Disagree$batch07$, $batch07$Huang: Most people who commit violent crimes do not carefully consider whether or how they will be punished for these crimes. And those who don't commit violent crimes have no inclination to do so. Rather than impose harsh mandatory sentences, we should attend to the root causes of violence to reduce the rate of violent crime. Suarez: Would you say the same about nonviolent crimes, such as tax evasion? Surely mandatory penalties are a useful deterrent in these cases. At any rate, I am confident that mandatory sentences prevent most people who would otherwise physically harm others from doing so.$batch07$, $batch07$The dialogue between Huang and Suarez most strongly supports the claim that they disagree about whether$batch07$, $batch07$D$batch07$, true, $batch07$Batch 07; question text from local bank.$batch07$ FROM lr_sections s WHERE s.preptest=128 AND s.section=3 AND NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch07$PT128-S3-Q4$batch07$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch07$A$batch07$, $batch07$the best way to reduce violent crime is to address the root causes of violence$batch07$, $batch07$Half Scope$batch07$, false FROM lr_questions q WHERE q.qid=$batch07$PT128-S3-Q4$batch07$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch07$A$batch07$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch07$B$batch07$, $batch07$people who commit violent crimes deserve harsh punishment$batch07$, $batch07$Out of Scope$batch07$, false FROM lr_questions q WHERE q.qid=$batch07$PT128-S3-Q4$batch07$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch07$B$batch07$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch07$C$batch07$, $batch07$people who commit violent crimes carefully consider how they will be punished for their crimes$batch07$, $batch07$Half Scope$batch07$, false FROM lr_questions q WHERE q.qid=$batch07$PT128-S3-Q4$batch07$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch07$C$batch07$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch07$D$batch07$, $batch07$mandatory sentences will deter most people who might otherwise commit violent crimes$batch07$, $batch07$Correct$batch07$, true FROM lr_questions q WHERE q.qid=$batch07$PT128-S3-Q4$batch07$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch07$D$batch07$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch07$E$batch07$, $batch07$severe penalties reduce the incidence of tax evasion$batch07$, $batch07$Half Scope$batch07$, false FROM lr_questions q WHERE q.qid=$batch07$PT128-S3-Q4$batch07$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch07$E$batch07$) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch07$PT128-S3-Q4$batch07$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch07$Huang's Position$batch07$, $batch07$Violent criminals don't think about punishment, and people who don't commit violence don't want to. So instead of harsh mandatory sentences, we should address the root causes of violence.$batch07$), (1, $batch07$Suarez's Position$batch07$, $batch07$Mandatory penalties deter nonviolent crimes like tax evasion. And mandatory sentences prevent most people who would otherwise physically harm others from doing it.$batch07$), (2, $batch07$Evaluate$batch07$, $batch07$Huang's premises add up to one claim: punishment doesn't deter violent crime. Those who commit it don't weigh punishment, and everyone else didn't need deterring. Suarez's last sentence denies exactly that. The tax evasion example is a side point Huang never addresses.$batch07$), (3, $batch07$Goal$batch07$, $batch07$Whether mandatory sentences deter people who would otherwise commit violent crimes.$batch07$)) v(position,label,body) WHERE q.qid=$batch07$PT128-S3-Q4$batch07$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch07$A$batch07$, $batch07$Huang holds this. Suarez defends mandatory sentences but never says addressing root causes isn't the best approach.$batch07$), ($batch07$B$batch07$, $batch07$Neither speaker talks about what violent criminals deserve.$batch07$), ($batch07$C$batch07$, $batch07$Huang says they don't carefully consider punishment. Suarez says sentences prevent violence, but Suarez never says criminals *carefully* weigh their punishment. Deterrence could work without that.$batch07$), ($batch07$D$batch07$, $batch07$Huang's reasons imply mandatory sentences don't deter violent crime. Suarez: they "prevent most people who would otherwise physically harm others from doing so".$batch07$), ($batch07$E$batch07$, $batch07$Suarez says this. Huang never mentions tax evasion.$batch07$)) v(letter,body) WHERE q.qid=$batch07$PT128-S3-Q4$batch07$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
